import './browser.js';
import './style.css';
import {Editor,Node,mergeAttributes} from '@tiptap/core';
import StarterKit from '@tiptap/starter-kit';
import Placeholder from '@tiptap/extension-placeholder';
import TaskList from '@tiptap/extension-task-list';
import TaskItem from '@tiptap/extension-task-item';
import Image from '@tiptap/extension-image';
import {Table,TableRow,TableHeader,TableCell} from '@tiptap/extension-table';
import {TextStyle,Color} from '@tiptap/extension-text-style';
import Highlight from '@tiptap/extension-highlight';
import {createIcons,icons} from 'lucide';
import {id,today,text,p,heading,task,seed,templates,contentText,toMarkdown} from './data.js';

const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>structuredClone(x), icon=(n,c='')=>`<i data-lucide="${n}" class="${c}"></i>`;
const btn=(action,label,ic='',extra='')=>`<button data-action="${action}" ${extra} title="${esc(label)}">${ic?icon(ic):''}<span>${esc(label)}</span></button>`;
const ib=(action,label,ic,extra='')=>{const match=extra.match(/class="([^"]*)"/);const cls=match?match[1]:'icon-button';return `<button class="${cls}" aria-label="${esc(label)}" title="${esc(label)}" data-action="${action}" ${extra.replace(/class="[^"]*"/,'')}>${icon(ic)}</button>`;};
let db,editor,saveTimer,searchTimer,current={view:'all',doc:null,folder:null},libraryQuery='',taskFilter='open',month=new Date(),listMode=false,loadFailed=false,saveState='Saved on this PC';
let activeSpace,dragDoc=null,boardCleanup=null,saveError=false;
const liveDocs=()=>db.docs.filter(d=>d.space===activeSpace&&!d.deleted&&!d.template);
const docById=x=>db.docs.find(d=>d.id===x);
function refreshIcons(){createIcons({icons,attrs:{'stroke-width':1.65}});}
function toast(message,error=false){let el=$('#toast');el.textContent=message;el.className='toast visible'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4500);}
function updateSaveLabel(){const el=$('#save-status');if(el){el.innerHTML=icon(saveError?'triangle-alert':'hard-drive')+esc(saveState);refreshIcons();}}
async function persist(){clearTimeout(saveTimer);if(loadFailed)return;saveState='Saving…';updateSaveLabel();try{await window.folio.save(clone(db));saveError=false;saveState='Saved on this PC';}catch(e){saveError=true;saveState='Save failed — export a backup';toast(e.message,true);}updateSaveLabel();}
function changed(d){if(d)d.updated=Date.now();clearTimeout(saveTimer);saveState='Saving…';updateSaveLabel();saveTimer=setTimeout(persist,350);}
function flushEditor(){if(editor){const d=docById(current.doc);if(d&&d.kind!=='collection'&&d.kind!=='board')d.content=editor.getJSON();}}
function dispose(){flushEditor();if(editor){editor.destroy();editor=null;}if(boardCleanup){boardCleanup();boardCleanup=null;}}
function navigate(view,doc=null,folder=null){dispose();current={view,doc,folder};libraryQuery='';render();$('#main')?.scrollTo(0,0);}
function newDoc(template=null,extra={}){const d={id:id(),title:template?.name||'Untitled',emoji:template?.emoji||'✦',cover:null,content:{type:'doc',content:clone(template?.content||[p()])},tags:[],space:activeSpace,folder:current.folder||null,created:Date.now(),updated:Date.now(),...extra};db.docs.push(d);changed(d);navigate('doc',d.id);setTimeout(()=>{$('#doc-title')?.focus();$('#doc-title')?.select();},50);return d;}
function dateTitle(date){return new Date(date+'T12:00:00').toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'});}
function daily(date=today()){let d=liveDocs().find(d=>d.daily===date);if(!d)d=newDoc(null,{title:dateTitle(date),emoji:'☀',daily:date,content:{type:'doc',content:[heading('On my mind'),p(),heading('Today’s focus'),{type:'taskList',content:[task('One thing that matters today')]}]}});else navigate('doc',d.id);}
function folderTree(parent=null,depth=0,seen=new Set()){
 return db.folders.filter(f=>f.space===activeSpace&&(f.parent||null)===parent&&!seen.has(f.id)).map(f=>{const next=new Set(seen);next.add(f.id);return `<div class="folder-row" data-folder="${f.id}" style="--depth:${depth}">${btn('folder',f.name,'folder',`data-id="${f.id}" class="nav-item ${current.folder===f.id?'active':''}"`)}${ib('folder-menu','Folder options','ellipsis',`data-id="${f.id}"`)}</div>`+folderTree(f.id,depth+1,next);}).join('');
}
function render(){
 dispose();
 document.documentElement.dataset.theme=db.settings.theme||'light';
 const space=db.spaces.find(s=>s.id===activeSpace)||db.spaces[0];activeSpace=space.id;
 $('#app').innerHTML=`<aside class="sidebar"><div class="brand"><div class="brand-mark">f</div><strong>folio</strong>${ib('settings','Settings','settings-2')}</div><button class="space-switch" data-action="spaces"><span class="space-avatar">${esc(space.emoji||'◒')}</span><span>${esc(space.name)}<small>Private workspace</small></span>${icon('chevrons-up-down')}</button><button class="search-nav" data-action="search">${icon('search')}<span>Search anything</span><kbd>Ctrl K</kbd></button><nav>${btn('home','All documents','files',`class="nav-item ${current.view==='all'&&!current.folder?'active':''}"`)}${btn('today','Daily notes','calendar-days',`class="nav-item ${current.view==='calendar'?'active':''}"`)}${btn('tasks','Tasks','circle-check',`class="nav-item ${current.view==='tasks'?'active':''}"`)}${btn('favorites','Starred','star',`class="nav-item ${current.view==='favorites'?'active':''}"`)}</nav><div class="side-heading"><span>FOLDERS</span>${ib('add-folder','New folder','plus')}</div><div class="folders">${folderTree()}</div><div class="side-heading"><span>STARRED</span></div><div class="starred-list">${liveDocs().filter(d=>d.starred).slice(0,6).map(d=>`<button class="nav-item small ${current.doc===d.id?'active':''}" data-action="open" data-id="${d.id}"><span class="tiny-emoji">${esc(d.emoji)}</span><span>${esc(d.title)}</span></button>`).join('')||'<span class="sidebar-empty">Keep favorites close.</span>'}</div><div class="sidebar-bottom">${btn('templates','Templates','layout-template',`class="nav-item ${current.view==='templates'?'active':''}"`)}${btn('trash','Trash','trash-2',`class="nav-item ${current.view==='trash'?'active':''}"`)}<div class="local-badge">${icon('shield-check')}<span>Just you. Just this computer.</span></div></div></aside><section class="workspace"><header class="topbar"><div class="breadcrumbs">${ib('home','All documents','panel-left')}<span>${esc(space.name)}</span><span class="crumb-slash">/</span><span id="crumb-current"></span></div><div class="top-actions"><span id="save-status"></span>${ib('search','Search · Ctrl K','search')}${ib('new-menu','Create something','plus')}</div></header><main id="main"></main></section><div id="overlay"></div><div id="slash-root"></div><div id="toast" class="toast" role="status"></div>`;
 renderMain();updateSaveLabel();refreshIcons();
 $$('.folder-row').forEach(el=>{el.ondragover=e=>{e.preventDefault();el.classList.add('drop-target');};el.ondragleave=()=>el.classList.remove('drop-target');el.ondrop=e=>{e.preventDefault();el.classList.remove('drop-target');const d=docById(dragDoc);if(d){d.folder=el.dataset.folder;d.parent=null;changed(d);navigate('all');toast('Moved to folder');}};});
}
function renderMain(){
 const names={all:'All documents',favorites:'Starred',doc:docById(current.doc)?.title||'Document',tasks:'Tasks',calendar:'Daily notes',templates:'Templates',trash:'Trash'};
 $('#crumb-current').textContent=current.folder?db.folders.find(f=>f.id===current.folder)?.name:names[current.view];
 $('#main').className='main '+(current.view==='doc'?'document-main':'');
 if(current.view==='doc')renderDocument();else if(current.view==='tasks')renderTasks();else if(current.view==='calendar')renderCalendar();else if(current.view==='templates')renderTemplates();else renderLibrary();refreshIcons();
}
function renderLibrary(){
 let docs=current.view==='trash'?db.docs.filter(d=>d.space===activeSpace&&d.deleted):liveDocs().filter(d=>!d.parent);
 if(current.view==='favorites')docs=liveDocs().filter(d=>d.starred);
 if(current.folder)docs=docs.filter(d=>d.folder===current.folder);
 if(libraryQuery)docs=docs.filter(d=>(d.title+' '+d.tags.join(' ')+' '+contentText(d.content)).toLowerCase().includes(libraryQuery.toLowerCase()));
 docs.sort((a,b)=>b.updated-a.updated);
 const title=current.folder?db.folders.find(f=>f.id===current.folder)?.name:current.view==='favorites'?'Close to heart':current.view==='trash'?'Trash':'A home for your ideas';
 $('#main').innerHTML=`<div class="library-head"><div><div class="eyebrow">${current.view==='trash'?'A SECOND CHANCE':new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'}).toUpperCase()}</div><h1>${esc(title)}</h1><p>${current.view==='trash'?'Restore a document whenever you need it.':'Room for notes, plans, and whatever comes next.'}</p></div>${current.view!=='trash'?btn('new-menu','New document','plus','class="primary"'):''}</div>${current.view==='all'&&!current.folder&&!libraryQuery?`<div class="daily-banner"><span class="sun">${icon('sun')}</span><div><strong>A fresh page for today</strong><p>Clear your head. Capture a thought. Make a little progress.</p></div>${btn('daily','Open daily note','arrow-up-right')}</div>`:''}<div class="list-toolbar"><div class="tabs"><button class="selected">${current.view==='trash'?'Deleted':'All documents'} <small>${docs.length}</small></button></div><div class="view-tools"><div class="filter-input">${icon('search')}<input id="library-filter" placeholder="Filter documents" value="${esc(libraryQuery)}"></div>${ib('toggle-view',listMode?'Grid view':'List view',listMode?'layout-grid':'list')}</div></div><div class="document-grid ${listMode?'as-list':''}">${docs.map(card).join('')}</div>${docs.length===0?`<div class="empty-state">${icon(current.view==='trash'?'trash-2':'notebook-pen')}<h2>${libraryQuery?'No matching documents':'A little space to start'}</h2><p>${libraryQuery?'Try a different word.':'Your next good idea belongs here.'}</p>${current.view!=='trash'?btn('new','Create a document','plus','class="primary"'):''}</div>`:''}<div class="library-footer">${docs.length} ${docs.length===1?'document':'documents'}<span>Made for thinking. Saved locally.</span></div>`;
 $('#library-filter').oninput=e=>{const start=e.target.selectionStart;libraryQuery=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{renderMain();const input=$('#library-filter');input.focus();input.setSelectionRange(start,start);},180);};
 $$('.doc-card').forEach(el=>{el.ondragstart=()=>dragDoc=el.dataset.id;});
}
function card(d){const preview=contentText(d.content).replace(/\s+/g,' ').slice(0,135);return `<article class="doc-card" draggable="true" data-id="${d.id}"><button class="card-open" data-action="open" data-id="${d.id}"><div class="card-cover ${esc(d.cover||'paper')}"><span class="cover-art"></span><span class="cover-emoji">${esc(d.emoji)}</span>${d.kind==='collection'?'<span class="type-badge">COLLECTION</span>':d.kind==='board'?'<span class="type-badge">WHITEBOARD</span>':d.daily?'<span class="type-badge">DAILY NOTE</span>':''}</div><div class="card-body"><h3>${esc(d.title)}</h3><p>${esc(preview|| (d.kind==='board'?'A little room to connect the dots.':'Your next thought starts here.'))}</p><div class="card-meta"><span>${d.tags.length?'#'+esc(d.tags[0]):d.kind==='collection'?(d.rows?.length||0)+' items':'Document'}</span><span>${new Date(d.updated).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span></div></div></button>${ib('card-menu','Document options','ellipsis',`data-id="${d.id}" class="icon-button card-options"`)}${d.starred?'<span class="card-star">'+icon('star')+'</span>':''}</article>`;}

const DueTask=TaskItem.extend({addAttributes(){return {...this.parent?.(),due:{default:null,parseHTML:el=>el.getAttribute('data-due'),renderHTML:a=>a.due?{'data-due':a.due}:{}}};}});
const NoteLink=Node.create({name:'noteLink',group:'inline',inline:true,atom:true,addAttributes(){return{target:{default:''},title:{default:'Page'}};},parseHTML(){return[{tag:'span[data-note-link]'}];},renderHTML({HTMLAttributes}){return['span',mergeAttributes(HTMLAttributes,{'data-note-link':HTMLAttributes.target,class:'note-link'}),'↗ '+HTMLAttributes.title];}});
const Attachment=Node.create({name:'attachment',group:'block',atom:true,addAttributes(){return{src:{default:''},name:{default:'Attachment'}};},parseHTML(){return[{tag:'a[data-attachment]'}];},renderHTML({HTMLAttributes}){return['a',{'data-attachment':'true',href:HTMLAttributes.src,download:HTMLAttributes.name,class:'attachment'},'↓ '+HTMLAttributes.name];}});
function renderDocument(){
 const d=docById(current.doc);if(!d){navigate('all');return;}
 $('#main').innerHTML=`<div class="doc-actions"><div>${d.deleted?'<span class="deleted-label">This document is in Trash</span>':`<span class="doc-updated">${d.daily?esc(dateTitle(d.daily)):'Edited '+new Date(d.updated).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span>`}</div><div>${d.deleted?btn('restore','Restore','undo-2',`data-id="${d.id}"`):`${ib('star',d.starred?'Unstar':'Star document','star',`data-id="${d.id}" class="icon-button ${d.starred?'is-starred':''}"`)}${ib('outline','Document outline','list-tree')}${ib('appearance','Page style','palette')}${ib('export-menu','Export document','download')}${ib('card-menu','Document options','ellipsis',`data-id="${d.id}"`)}`}</div></div><article class="document ${d.wide||db.settings.wide?'wide':''} font-${esc(d.font||db.settings.font||'sans')}">${d.cover?`<div class="page-cover ${esc(d.cover)}"><span class="cover-art"></span>${btn('appearance','Change cover','image')}</div>`:'<div class="no-cover">'+btn('appearance','Add cover','image')+'</div>'}<div class="document-body"><button class="document-emoji" data-action="emoji">${esc(d.emoji||'✦')}</button><input id="doc-title" class="document-title" aria-label="Document title" value="${esc(d.title)}" placeholder="Untitled"><div class="document-tags">${d.tags.map(t=>`<button data-action="edit-tags">#${esc(t)}</button>`).join('')}${btn('edit-tags',d.tags.length?'Edit tags':'Add tags','hash')}</div><div id="formatting"></div><div id="editor"></div><div id="special-content"></div><div class="subpages">${liveDocs().filter(c=>c.parent===d.id).map(c=>`<button data-action="open" data-id="${c.id}">${esc(c.emoji)} <strong>${esc(c.title)}</strong>${icon('arrow-up-right')}</button>`).join('')}</div>${d.kind?'':btn('subpage','Add a subpage','file-plus','class="subpage-add"')}<footer class="document-footer"><span id="word-count"></span><span>Private · Available offline</span></footer></div></article><input id="attachment-input" type="file" hidden>`;
 $('#doc-title').oninput=e=>{d.title=e.target.value;$('#crumb-current').textContent=d.title;changed(d);};
 if(d.kind==='collection'){renderCollection(d);$('#word-count').textContent=(d.rows?.length||0)+' items';}
 else if(d.kind==='board'){renderBoard(d);$('#word-count').textContent='Whiteboard';}
 else {
  renderFormatting();
  editor=new Editor({element:$('#editor'),extensions:[StarterKit.configure({link:{openOnClick:false,HTMLAttributes:{rel:'noopener noreferrer'}}}),Placeholder.configure({placeholder:'Start writing, or type / for blocks…'}),TaskList,DueTask.configure({nested:true}),Image.configure({allowBase64:true}),Table.configure({resizable:true}),TableRow,TableHeader,TableCell,TextStyle,Color,Highlight.configure({multicolor:true}),NoteLink,Attachment],content:d.content||{type:'doc',content:[p()]},editable:!d.deleted,
   editorProps:{attributes:{class:'writing-area',spellcheck:'true'},handleKeyDown(view,event){if(event.key==='/'&&!event.ctrlKey&&!event.metaKey){event.preventDefault();showInsert();return true;}return false;}},
   onUpdate:({editor:e})=>{d.content=e.getJSON();changed(d);wordCount();},onSelectionUpdate:()=>updateFormatting()});wordCount();
  $('#attachment-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>12*1024*1024){toast('Please choose a file smaller than 12 MB.',true);return;}const src=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});if(file.type.startsWith('image/'))editor.chain().focus().setImage({src,alt:file.name}).run();else editor.chain().focus().insertContent({type:'attachment',attrs:{src,name:file.name}}).run();};
 }
}
function wordCount(){if(!editor)return;const s=editor.getText().trim();$('#word-count').textContent=(s?s.split(/\s+/).length:0)+' words';}
function renderFormatting(){const tools=[['bold','Bold · Ctrl B','bold'],['italic','Italic · Ctrl I','italic'],['underline','Underline · Ctrl U','underline'],['strike','Strikethrough','strikethrough'],['sep'],['h1','Heading 1','heading-1'],['h2','Heading 2','heading-2'],['bullet','Bullet list','list'],['number','Numbered list','list-ordered'],['task','Task list','list-todo'],['quote','Quote','quote'],['sep'],['link','Add link','link'],['highlight','Highlight','highlighter'],['code','Code block','code'],['table','Insert table','table-2'],['insert','Insert block','plus']];$('#formatting').innerHTML=`<div class="format-bar">${tools.map(([a,t,i])=>a==='sep'?'<span class="separator"></span>':ib('format',t,i,`data-format="${a}"`)).join('')}<span class="format-spacer"></span>${ib('undo','Undo · Ctrl Z','undo-2')}${ib('redo','Redo · Ctrl Shift Z','redo-2')}</div>`;}
function updateFormatting(){if(!editor)return;$$('[data-format]').forEach(el=>{const a=el.dataset.format;const states={h1:()=>editor.isActive('heading',{level:1}),h2:()=>editor.isActive('heading',{level:2}),bullet:()=>editor.isActive('bulletList'),number:()=>editor.isActive('orderedList'),task:()=>editor.isActive('taskList'),quote:()=>editor.isActive('blockquote'),code:()=>editor.isActive('codeBlock')};el.classList.toggle('on',states[a]?states[a]():editor.isActive(a));});}
async function format(a){if(!editor)return;let c=editor.chain().focus();switch(a){case'bold':c.toggleBold().run();break;case'italic':c.toggleItalic().run();break;case'underline':c.toggleUnderline().run();break;case'strike':c.toggleStrike().run();break;case'h1':c.toggleHeading({level:1}).run();break;case'h2':c.toggleHeading({level:2}).run();break;case'h3':c.toggleHeading({level:3}).run();break;case'paragraph':c.setParagraph().run();break;case'bullet':c.toggleBulletList().run();break;case'number':c.toggleOrderedList().run();break;case'task':c.toggleTaskList().run();break;case'quote':c.toggleBlockquote().run();break;case'code':c.toggleCodeBlock().run();break;case'highlight':c.toggleHighlight({color:'#fff0a7'}).run();break;case'table':c.insertTable({rows:3,cols:3,withHeaderRow:true}).run();break;case'line':c.setHorizontalRule().run();break;case'image':case'file':$('#attachment-input').click();break;case'link':{const href=await ask('Add a link',[{name:'url',label:'Web address',value:editor.getAttributes('link').href||'https://'}]);if(href&&/^https?:\/\//i.test(href.url))editor.chain().focus().extendMarkRange('link').setLink({href:href.url}).run();else if(href)toast('Use a link beginning with https:// or http://.',true);break;}case'note-link':chooseNote();break;case'date':c.insertContent(new Date().toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})).run();break;case'insert':showInsert();break;case'add-row':c.addRowAfter().run();break;case'add-column':c.addColumnAfter().run();break;case'delete-row':c.deleteRow().run();break;case'delete-table':c.deleteTable().run();break;case'color':{const r=await ask('Text color',[{name:'color',label:'Color',type:'color',value:'#47745d'}]);if(r)editor.chain().focus().setColor(r.color).run();break;}}updateFormatting();editor?.view.focus();}
const insertChoices=[['paragraph','Text','type'],['h1','Heading 1','heading-1'],['h2','Heading 2','heading-2'],['h3','Heading 3','heading-3'],['bullet','Bullet list','list'],['number','Numbered list','list-ordered'],['task','Task list','list-todo'],['quote','Quote / callout','quote'],['table','Table','table-2'],['image','Image from computer','image'],['file','File attachment','paperclip'],['code','Code block','code'],['line','Divider','minus'],['note-link','Link to a document','file-symlink'],['date','Today’s date','calendar'],['color','Text color','palette'],['add-row','Table: add row','rows-3'],['add-column','Table: add column','columns-3'],['delete-row','Table: delete row','list-minus'],['delete-table','Delete table','table-2']];
function showInsert(){modal(`<div class="modal-heading"><div><h2>Make room for a thought</h2><p>Choose a block to add to your page.</p></div>${ib('close-modal','Close','x')}</div><input class="modal-search" id="insert-query" placeholder="Find a block…" autofocus><div class="insert-grid">${insertChoices.map(([a,t,i])=>btn('insert-choice',t,i,`data-format="${a}"`)).join('')}</div>`,'insert-modal');$('#insert-query').oninput=e=>$$('[data-action="insert-choice"]').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(e.target.value.toLowerCase()));}
function chooseNote(){modal(`<div class="modal-heading"><h2>Link a document</h2>${ib('close-modal','Close','x')}</div><div class="choice-list">${liveDocs().filter(d=>d.id!==current.doc).map(d=>`<button data-action="insert-note-link" data-id="${d.id}">${esc(d.emoji)} ${esc(d.title)}</button>`).join('')}</div>`);}

function modal(html,cls=''){const overlay=$('#overlay');overlay.innerHTML=`<div class="modal-backdrop"><section class="modal ${cls}" role="dialog" aria-modal="true">${html}</section></div>`;overlay.querySelector('.modal-backdrop').onclick=e=>{if(e.target===e.currentTarget)closeModal();};refreshIcons();setTimeout(()=>$('[autofocus]',overlay)?.focus(),30);}
let resolveAsk=null;
function closeModal(){if(resolveAsk){resolveAsk(null);resolveAsk=null;}$('#overlay').innerHTML='';}
function ask(title,fields,submit='Save'){return new Promise(resolve=>{resolveAsk=resolve;modal(`<div class="modal-heading"><h2>${esc(title)}</h2>${ib('close-modal','Close','x')}</div><form id="ask-form">${fields.map(f=>`<label class="field"><span>${esc(f.label)}</span>${f.options?`<select name="${esc(f.name)}">${f.options.map(o=>`<option value="${esc(o.value??o)}" ${(o.value??o)===f.value?'selected':''}>${esc(o.label??o)}</option>`).join('')}</select>`:`<input name="${esc(f.name)}" type="${f.type||'text'}" value="${esc(f.value||'')}" ${f.required===false?'':'required'} autofocus>`}</label>`).join('')}<div class="modal-footer">${btn('close-modal','Cancel','','type="button"')}<button type="submit" class="primary">${esc(submit)}</button></div></form>`);$('#ask-form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));resolveAsk=null;closeModal();resolve(values);};});}
function menu(title,items){modal(`<div class="modal-heading"><h2>${esc(title)}</h2>${ib('close-modal','Close','x')}</div><div class="choice-list">${items.map(([a,l,i,extra=''])=>btn(a,l,i,extra)).join('')}</div>`,'menu-modal');}
function search(){modal(`<div class="search-dialog-head">${icon('search')}<input id="global-search" placeholder="Search your documents, text, and tags…" autofocus>${ib('close-modal','Close','x')}</div><div id="search-results" class="search-results"></div><div class="search-tip">Everything here stays on this computer.</div>`,'search-modal');const input=$('#global-search');const run=()=>{const q=input.value.toLowerCase().trim();const docs=liveDocs().filter(d=>!q||(d.title+' '+contentText(d.content)+' '+d.tags.join(' ')).toLowerCase().includes(q));$('#search-results').innerHTML=docs.slice(0,40).map(d=>`<button data-action="search-open" data-id="${d.id}"><span class="result-icon">${esc(d.emoji)}</span><div><strong>${esc(d.title)}</strong><p>${esc(contentText(d.content).slice(0,100))}</p></div>${icon('arrow-up-right')}</button>`).join('')||'<p class="empty-small">Nothing found. Try another word.</p>';refreshIcons();};input.oninput=run;input.onkeydown=e=>{if(e.key==='Enter')$('#search-results button')?.click();};run();}

function allTasks(){let out=[];for(const d of liveDocs()){const walk=(node,path=[])=>{if(node.type==='taskItem')out.push({doc:d,node,path,text:contentText(node).trim()});node.content?.forEach((n,i)=>walk(n,[...path,i]));};walk(d.content);}return out;}
function renderTasks(){const tasks=allTasks();let selected=tasks.filter(t=>taskFilter==='all'||(taskFilter==='done'?t.node.attrs.checked:taskFilter==='today'?!t.node.attrs.checked&&t.node.attrs.due&&t.node.attrs.due<=today():!t.node.attrs.checked));$('#main').innerHTML=`<div class="library-head"><div><div class="eyebrow">ONE THING AT A TIME</div><h1>A little more done</h1><p>Every next step, together in one place.</p></div><span class="task-summary">${tasks.filter(t=>t.node.attrs.checked).length} of ${tasks.length} complete</span></div><form id="quick-task" class="quick-task">${icon('plus')}<input name="task" aria-label="New task" placeholder="What needs doing?" required><input type="date" name="due" aria-label="Due date"><button class="primary">Add task</button></form><div class="tabs task-tabs">${[['open','Upcoming'],['today','Today & overdue'],['done','Completed'],['all','All tasks']].map(([a,l])=>`<button data-action="task-filter" data-filter="${a}" class="${taskFilter===a?'selected':''}">${l}</button>`).join('')}</div><div class="task-list">${selected.map(t=>`<div class="task-row ${t.node.attrs.checked?'completed':''}"><input type="checkbox" aria-label="Complete ${esc(t.text)}" data-task-doc="${t.doc.id}" data-path="${t.path.join('.')}" ${t.node.attrs.checked?'checked':''}><button class="task-title" data-action="open" data-id="${t.doc.id}"><span>${esc(t.text||'Untitled task')}</span><small>${esc(t.doc.emoji)} ${esc(t.doc.title)}</small></button><input class="task-date ${t.node.attrs.due&&t.node.attrs.due<today()&&!t.node.attrs.checked?'overdue':''}" type="date" aria-label="Task due date" value="${esc(t.node.attrs.due||'')}" data-due-doc="${t.doc.id}" data-path="${t.path.join('.')}"></div>`).join('')||`<div class="empty-state">${icon('circle-check')}<h2>A clear horizon</h2><p>${taskFilter==='today'?'Nothing due today. Enjoy a little breathing room.':'Add a task above, or use a task block in any document.'}</p></div>`}</div>`;
 $('#quick-task').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);let inbox=liveDocs().find(d=>d.inbox);if(!inbox){inbox={id:id(),title:'Task inbox',emoji:'☑',space:activeSpace,content:{type:'doc',content:[]},tags:[],created:Date.now(),inbox:true};db.docs.push(inbox);}if(!inbox.content.content.some(n=>n.type==='taskList'))inbox.content.content.push({type:'taskList',content:[]});inbox.content.content.find(n=>n.type==='taskList').content.push(task(f.get('task'),false,f.get('due')||null));changed(inbox);renderMain();};
 $$('[data-task-doc]').forEach(el=>el.onchange=()=>{const d=docById(el.dataset.taskDoc);let n=d.content;el.dataset.path.split('.').forEach(i=>n=n.content[+i]);n.attrs.checked=el.checked;changed(d);renderMain();});
 $$('[data-due-doc]').forEach(el=>el.onchange=()=>{const d=docById(el.dataset.dueDoc);let n=d.content;el.dataset.path.split('.').forEach(i=>n=n.content[+i]);n.attrs.due=el.value||null;changed(d);renderMain();});
}
function renderCalendar(){const year=month.getFullYear(),m=month.getMonth(),first=new Date(year,m,1),start=new Date(year,m,1-first.getDay());const days=Array.from({length:42},(_,i)=>{let d=new Date(start);d.setDate(start.getDate()+i);return d;});$('#main').innerHTML=`<div class="library-head"><div><div class="eyebrow">MAKE A LITTLE TIME</div><h1>Your days, collected</h1><p>A small ritual. A thought to come back to.</p></div>${btn('daily','Today’s note','plus','class="primary"')}</div><div class="calendar-toolbar"><h2>${first.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2><div>${ib('prev-month','Previous month','chevron-left')}${btn('this-month','Today')}${ib('next-month','Next month','chevron-right')}</div></div><div class="calendar"><div class="weekdays">${['SUN','MON','TUE','WED','THU','FRI','SAT'].map(s=>`<span>${s}</span>`).join('')}</div><div class="calendar-grid">${days.map(date=>{const key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`,note=liveDocs().find(d=>d.daily===key),due=allTasks().filter(t=>!t.node.attrs.checked&&t.node.attrs.due===key).length;return `<button data-action="daily-date" data-date="${key}" class="calendar-day ${date.getMonth()!==m?'muted':''} ${key===today()?'is-today':''}"><span class="day-number">${date.getDate()}</span>${note?'<span class="day-note">'+icon('file-text')+' Daily note</span>':''}${due?`<small>${due} task${due===1?'':'s'} due</small>`:''}</button>`;}).join('')}</div></div>`;}
function renderTemplates(){const custom=db.docs.filter(d=>d.space===activeSpace&&d.template&&!d.deleted);$('#main').innerHTML=`<div class="library-head"><div><div class="eyebrow">A LITTLE HEAD START</div><h1>Skip the blank page</h1><p>Thoughtful starting points. Make them your own.</p></div></div><div class="template-grid">${templates.map((t,i)=>`<button class="template-card" data-action="use-template" data-index="${i}"><div class="template-preview"><span>${t.emoji}</span><div class="preview-lines"><b></b><i></i><i></i><b></b><i></i><i></i></div></div><h3>${esc(t.name)}</h3><p>${esc(t.description)}</p><span class="template-use">Use template ${icon('arrow-up-right')}</span></button>`).join('')}${custom.map(d=>`<button class="template-card" data-action="use-custom-template" data-id="${d.id}"><div class="template-preview"><span>${esc(d.emoji)}</span><div class="preview-lines"><b></b><i></i><i></i></div></div><h3>${esc(d.title)}</h3><p>Your saved template.</p><span class="template-use">Use template ${icon('arrow-up-right')}</span></button>`).join('')}</div>`;}

function renderCollection(d){d.columns ||= [{id:'name',name:'Name',type:'text'}];d.rows ||= [];const gallery=d.collectionView==='gallery';$('#special-content').innerHTML=`<p class="collection-intro">${esc(contentText(d.content)||'Keep related things together. Double-click an item name to open its page.')}</p><div class="collection-tools"><div class="tabs"><button data-action="collection-view" data-view="table" class="${!gallery?'selected':''}">${icon('table-2')} Table</button><button data-action="collection-view" data-view="gallery" class="${gallery?'selected':''}">${icon('layout-grid')} Gallery</button></div><div>${btn('collection-column','Add field','columns-3')}${btn('collection-row','New item','plus','class="primary"')}</div></div>${gallery?`<div class="collection-gallery">${d.rows.map(row=>`<div class="collection-card"><button class="collection-card-title" data-action="collection-open" data-id="${row.id}">${esc(row.name||'Untitled')}</button>${d.columns.filter(c=>c.id!=='name').map(col=>`<label><span>${esc(col.name)}</span>${cell(row,col)}</label>`).join('')}${ib('collection-delete','Remove item','trash-2',`data-id="${row.id}"`)}</div>`).join('')}</div>`:`<div class="collection-table-wrap"><table class="collection-table"><thead><tr>${d.columns.map(c=>`<th><button data-action="column-rename" data-id="${c.id}">${esc(c.name)} ${icon(c.type==='date'?'calendar':c.type==='checkbox'?'check-square':'chevrons-up-down')}</button></th>`).join('')}<th></th></tr></thead><tbody>${d.rows.map(row=>`<tr>${d.columns.map(col=>`<td>${cell(row,col)}</td>`).join('')}<td>${ib('collection-open','Open item page','arrow-up-right',`data-id="${row.id}"`)}${ib('collection-delete','Remove item','x',`data-id="${row.id}"`)}</td></tr>`).join('')}</tbody></table>${btn('collection-row','Add an item','plus','class="table-add"')}</div>`}`;
 $$('[data-cell]').forEach(el=>{el.onchange=()=>{const row=d.rows.find(r=>r.id===el.dataset.row);row[el.dataset.cell]=el.type==='checkbox'?el.checked:el.value;changed(d);};if(el.dataset.cell==='name')el.ondblclick=()=>openCollectionItem(d,el.dataset.row);});
}
function cell(row,c){const attrs=`data-cell="${c.id}" data-row="${row.id}" aria-label="${esc(c.name)}"`;if(c.type==='select')return `<select ${attrs} class="status-select">${['To do','In progress','Done','Someday'].map(s=>`<option ${row[c.id]===s?'selected':''}>${s}</option>`).join('')}</select>`;return `<input ${attrs} type="${c.type==='date'?'date':c.type==='number'?'number':c.type==='checkbox'?'checkbox':'text'}" ${c.type==='checkbox'?(row[c.id]?'checked':''):`value="${esc(row[c.id]||'')}"`} placeholder="${c.id==='name'?'Untitled':'—'}">`;}
function openCollectionItem(d,rowId){const row=d.rows.find(r=>r.id===rowId);if(row.noteId&&docById(row.noteId))navigate('doc',row.noteId);else{const item=newDoc(null,{title:row.name||'Untitled item',parent:d.id,emoji:'◈'});row.noteId=item.id;changed(d);}}
function renderBoard(d){d.board ||= {strokes:[],notes:[]};$('#special-content').innerHTML=`<div class="board-toolbar"><span>${icon('pencil')} Draw to connect your ideas</span><div><input type="color" id="pen-color" value="#426451" aria-label="Pen color">${btn('board-note','Sticky note','sticky-note')}${ib('board-undo','Undo last stroke','undo-2')}${ib('board-clear','Clear drawing','eraser')}</div></div><div class="board-surface"><canvas id="whiteboard" width="1200" height="750"></canvas><div id="sticky-layer"></div></div><p class="board-hint">Draw with your mouse or pen. Drag a note by its top edge. Double-click its text to edit.</p>`;
 const canvas=$('#whiteboard'),ctx=canvas.getContext('2d'),layer=$('#sticky-layer');let drawing=null;
 const repaint=()=>{ctx.clearRect(0,0,1200,750);for(const stroke of [...d.board.strokes,...(drawing?[drawing]:[])]){if(stroke.points.length<2)continue;ctx.strokeStyle=stroke.color;ctx.lineWidth=3;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();stroke.points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.stroke();}};
 const notes=()=>{layer.innerHTML=d.board.notes.map(n=>`<div class="sticky" data-sticky="${n.id}" style="left:${n.x/12}%;top:${n.y/7.5}%;background:${n.color}"><div class="sticky-grip">${icon('grip-horizontal')}${ib('board-delete-note','Delete note','x',`data-id="${n.id}"`)}</div><div class="sticky-text">${esc(n.text).replace(/\n/g,'<br>')}</div></div>`).join('');refreshIcons();$$('[data-sticky]').forEach(el=>{const n=d.board.notes.find(n=>n.id===el.dataset.sticky);$('.sticky-text',el).ondblclick=async()=>{const result=await ask('Edit note',[{name:'text',label:'Your thought',value:n.text}]);if(result){n.text=result.text;changed(d);notes();}};$('.sticky-grip',el).onpointerdown=e=>{if(e.target.closest('button'))return;const rect=canvas.getBoundingClientRect(),x=e.clientX,y=e.clientY,ox=n.x,oy=n.y;el.setPointerCapture(e.pointerId);el.onpointermove=ev=>{n.x=Math.max(0,Math.min(950,ox+(ev.clientX-x)*1200/rect.width));n.y=Math.max(0,Math.min(570,oy+(ev.clientY-y)*750/rect.height));el.style.left=n.x/12+'%';el.style.top=n.y/7.5+'%';};el.onpointerup=()=>{el.onpointermove=null;el.onpointerup=null;changed(d);};};});};
 const point=e=>{const r=canvas.getBoundingClientRect();return[(e.clientX-r.left)*1200/r.width,(e.clientY-r.top)*750/r.height];};
 canvas.onpointerdown=e=>{drawing={color:$('#pen-color').value,points:[point(e)]};canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(drawing){drawing.points.push(point(e));repaint();}};canvas.onpointerup=()=>{if(drawing){d.board.strokes.push(drawing);drawing=null;changed(d);repaint();}};canvas.onpointercancel=canvas.onpointerup;
 window.boardRepaint=repaint;window.boardNotes=notes;boardCleanup=()=>{window.boardRepaint=null;window.boardNotes=null;};repaint();notes();
}

function appearance(){const d=docById(current.doc);modal(`<div class="modal-heading"><div><h2>Set the mood</h2><p>A page that feels like you.</p></div>${ib('close-modal','Close','x')}</div><div class="field"><span>Cover</span><div class="cover-choices">${['none','sage','sand','lavender','blue','rose','ink'].map(c=>`<button data-action="set-cover" data-cover="${c}" class="cover-choice ${c}" aria-label="${c} cover"><span class="cover-art"></span>${c==='none'?icon('ban'):''}</button>`).join('')}</div></div><div class="field"><span>Typography</span><div class="segmented">${[['sans','Modern'],['serif','Literary'],['mono','Typewriter']].map(([a,l])=>btn('set-font',l,'',`data-font="${a}" class="${(d.font||db.settings.font)===a?'selected':''}"`)).join('')}</div></div><div class="field"><span>Page width</span><div class="segmented">${btn('set-width','Comfortable','',`data-wide="false" class="${!d.wide?'selected':''}"`)}${btn('set-width','Wide','',`data-wide="true" class="${d.wide?'selected':''}"`)}</div></div>`);}
async function settings(){const path=await window.folio.dataPath();modal(`<div class="modal-heading"><div><h2>Your little corner</h2><p>Offline by design. Yours to keep.</p></div>${ib('close-modal','Close','x')}</div><div class="settings-card"><strong>Appearance</strong><div class="segmented">${[['light','Light'],['dark','Dark']].map(([a,l])=>btn('theme',l,a==='light'?'sun':'moon',`data-theme="${a}" class="${db.settings.theme===a?'selected':''}"`)).join('')}</div></div><div class="settings-card"><strong>Keep a copy</strong><p>A workspace backup includes all spaces, documents, collections, boards, and attachments. Import merges it with your current workspace.</p><div class="button-row">${btn('backup','Export workspace','download','class="primary"')}${btn('import','Import backup / Markdown','upload')}</div></div><div class="settings-card"><strong>Saved on this computer</strong><p class="data-path">${esc(path)}</p><p>Changes are saved automatically. A previous-write backup is kept beside this file as workspace.json.bak.</p></div><div class="settings-foot">Folio 0.1 · Independent app inspired by Craft’s public examples.<br>No account, cloud sync, online AI, or collaboration service.</div>`,'settings-modal');}
async function exportDoc(type){flushEditor();const d=docById(current.doc);let content,extension=type,name=d.title.replace(/[<>:"/\\|?*]/g,'-');if(type==='md'){content='# '+d.title+'\n\n'+toMarkdown(d.content);if(d.kind==='collection')content+='\n'+d.columns.map(c=>c.name).join(' | ')+'\n'+d.rows.map(r=>d.columns.map(c=>r[c.id]||'').join(' | ')).join('\n');if(d.kind==='board')content+='\n'+d.board.notes.map(n=>'- '+n.text).join('\n');}else if(type==='json')content=JSON.stringify(d,null,2);else {extension='html';const body=editor?editor.getHTML():`<pre>${esc(toMarkdown(d.content))}</pre>`;content=`<!doctype html><html><head><meta charset="utf-8"><title>${esc(d.title)}</title><style>body{font:18px/1.7 Georgia,serif;max-width:800px;margin:70px auto;padding:0 28px;color:#282b29}img{max-width:100%}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccc;padding:8px}blockquote{border-left:3px solid #aaa;padding-left:20px}a{color:#47745d}</style></head><body><h1>${esc(d.title)}</h1>${body}</body></html>`;}if(await window.folio.exportFile({name:name+'.'+extension,extension,content}))toast('Export saved');}
async function importFile(){const file=await window.folio.importFile();if(!file)return;try{if(file.name.endsWith('.json')){const imported=JSON.parse(file.content);if(imported.version!==1||!Array.isArray(imported.docs)||!Array.isArray(imported.spaces)||!Array.isArray(imported.folders))throw new Error('Choose a Folio workspace backup.');const validId=x=>typeof x==='string'&&/^[a-zA-Z0-9-]+$/.test(x);if(!imported.spaces.length||!imported.spaces.every(s=>validId(s.id)&&typeof s.name==='string')||!imported.folders.every(f=>validId(f.id)&&typeof f.name==='string')||!imported.docs.every(d=>validId(d.id)&&typeof d.title==='string'&&Array.isArray(d.tags)&&d.tags.every(t=>typeof t==='string')))throw new Error('This backup contains invalid workspace entries.');const seen=new Set([...db.spaces,...db.folders,...db.docs].map(x=>x.id));const remap=new Map([...imported.spaces,...imported.folders,...imported.docs].map(x=>[x.id,seen.has(x.id)?id():x.id]));const ref=x=>remap.get(x)||x;const fixNode=n=>{if(n.type==='noteLink'&&n.attrs)n.attrs.target=ref(n.attrs.target);n.content?.forEach(fixNode);};imported.spaces.forEach(s=>{s.id=ref(s.id);db.spaces.push(s);});imported.folders.forEach(f=>{f.id=ref(f.id);f.space=ref(f.space);f.parent=ref(f.parent);db.folders.push(f);});imported.docs.forEach(d=>{d.id=ref(d.id);d.space=ref(d.space);d.folder=ref(d.folder);d.parent=ref(d.parent);d.rows?.forEach(r=>r.noteId=ref(r.noteId));if(d.content)fixNode(d.content);db.docs.push(d);});changed();closeModal();navigate('all');toast('Backup imported into its own spaces. Switch spaces to see it.');}else{const lines=file.content.split(/\r?\n/);const content=lines.map(line=>{const h=line.match(/^(#{1,3}) (.*)/);if(h)return heading(h[2],h[1].length);const t=line.match(/^- \[([ xX])\] (.*)/);if(t)return {type:'taskList',content:[task(t[2],t[1]!==' ')]};return p(line);});closeModal();newDoc(null,{title:file.name.replace(/\.(md|txt)$/i,''),content:{type:'doc',content}});toast('Text imported. Basic headings and tasks retained.');}}catch(e){toast(e.message,true);}}

document.addEventListener('click',async e=>{
 const note=e.target.closest('[data-note-link]');if(note){e.preventDefault();navigate('doc',note.getAttribute('data-note-link'));return;}
 const attachment=e.target.closest('a[data-attachment]');if(attachment){e.preventDefault();const a=document.createElement('a');a.href=attachment.href;a.download=attachment.download;a.click();return;}
 const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,doc=docById(el.dataset.id)||docById(current.doc);try{
 switch(a){
  case'home':navigate('all');break;case'open':case'search-open':closeModal();navigate('doc',el.dataset.id);break;case'folder':navigate('all',null,el.dataset.id);break;
  case'today':navigate('calendar');break;case'daily':daily();break;case'daily-date':daily(el.dataset.date);break;case'tasks':navigate('tasks');break;case'favorites':navigate('favorites');break;case'trash':navigate('trash');break;case'templates':navigate('templates');break;
  case'new':closeModal();newDoc();break;case'new-menu':menu('What would you like to make?',[['new','Document','file-text'],['new-collection','Collection','table-2'],['new-board','Whiteboard','pencil-ruler'],['new-daily','Daily note','calendar'],['go-templates','From a template','layout-template']]);break;
  case'new-collection':closeModal();newDoc(null,{title:'Untitled collection',emoji:'◈',kind:'collection',columns:[{id:'name',name:'Name',type:'text'},{id:'status',name:'Status',type:'select'},{id:'date',name:'Date',type:'date'}],rows:[]});break;
  case'new-board':closeModal();newDoc(null,{title:'Untitled whiteboard',emoji:'〰',kind:'board',board:{strokes:[],notes:[]}});break;
  case'new-daily':closeModal();daily();break;case'go-templates':closeModal();navigate('templates');break;
  case'add-folder':{const r=await ask('A home for related ideas',[{name:'name',label:'Folder name'}]);if(r){db.folders.push({id:id(),name:r.name,space:activeSpace,parent:current.folder});changed();render();}break;}
  case'folder-menu':menu('Folder options',[['folder-rename','Rename folder','pencil',`data-id="${el.dataset.id}"`],['folder-child','Add subfolder','folder-plus',`data-id="${el.dataset.id}"`],['folder-remove','Remove folder (keep documents)','folder-minus',`data-id="${el.dataset.id}"`]]);break;
  case'folder-rename':{const f=db.folders.find(f=>f.id===el.dataset.id),r=await ask('Rename folder',[{name:'name',label:'Name',value:f.name}]);if(r){f.name=r.name;changed();render();}break;}
  case'folder-child':{const r=await ask('New subfolder',[{name:'name',label:'Name'}]);if(r){db.folders.push({id:id(),name:r.name,space:activeSpace,parent:el.dataset.id});changed();render();}break;}
  case'folder-remove':{const f=db.folders.find(f=>f.id===el.dataset.id);db.docs.filter(d=>d.folder===f.id).forEach(d=>d.folder=f.parent);db.folders.filter(x=>x.parent===f.id).forEach(x=>x.parent=f.parent);db.folders=db.folders.filter(x=>x.id!==f.id);changed();closeModal();navigate('all');break;}
  case'toggle-view':listMode=!listMode;renderMain();break;case'search':search();break;case'close-modal':closeModal();break;
  case'format':format(el.dataset.format);break;case'insert-choice':{const f=el.dataset.format;closeModal();await format(f);break;}
  case'insert-note-link':{const d=docById(el.dataset.id);closeModal();editor?.chain().focus().insertContent({type:'noteLink',attrs:{target:d.id,title:d.title}}).run();break;}
  case'undo':editor?.commands.undo();break;case'redo':editor?.commands.redo();break;
  case'star':doc.starred=!doc.starred;changed(doc);dispose();render();break;
  case'emoji':{const r=await ask('Page icon',[{name:'emoji',label:'An emoji or symbol',value:doc.emoji}]);if(r){doc.emoji=r.emoji.slice(0,12);changed(doc);dispose();render();}break;}
  case'edit-tags':{const r=await ask('Tags',[{name:'tags',label:'Separate tags with commas',value:doc.tags.join(', '),required:false}]);if(r){doc.tags=[...new Set(r.tags.split(',').map(t=>t.trim().replace(/^#/,'' )).filter(Boolean))];changed(doc);dispose();render();}break;}
  case'appearance':appearance();break;case'set-cover':doc.cover=el.dataset.cover==='none'?null:el.dataset.cover;changed(doc);closeModal();dispose();render();appearance();break;
  case'set-font':doc.font=el.dataset.font;changed(doc);closeModal();dispose();render();appearance();break;case'set-width':doc.wide=el.dataset.wide==='true';changed(doc);closeModal();dispose();render();appearance();break;
  case'card-menu':menu(doc.title,[['rename','Rename','pencil',`data-id="${doc.id}"`],['duplicate','Duplicate','copy',`data-id="${doc.id}"`],['move','Move to folder','folder-input',`data-id="${doc.id}"`],['star-menu',doc.starred?'Unstar':'Add to Starred','star',`data-id="${doc.id}"`],['save-template','Save as template','layout-template',`data-id="${doc.id}"`],doc.deleted?['restore','Restore','undo-2',`data-id="${doc.id}"`]:['delete','Move to Trash','trash-2',`data-id="${doc.id}"`]]);break;
  case'rename':{const r=await ask('Rename document',[{name:'title',label:'Title',value:doc.title}]);if(r){doc.title=r.title;changed(doc);dispose();render();}break;}
  case'duplicate':case'save-template':{flushEditor();const d=clone(doc);d.id=id();d.title+=(a==='duplicate'?' — copy':' — template');d.template=a==='save-template';d.daily=null;d.parent=null;d.starred=false;d.created=d.updated=Date.now();db.docs.push(d);changed(d);closeModal();if(a==='duplicate')navigate('doc',d.id);else{toast('Saved to Templates');navigate('templates');}break;}
  case'move':{const r=await ask('Move document',[{name:'folder',label:'Folder',value:doc.folder||'',options:[{value:'',label:'All documents'},...db.folders.filter(f=>f.space===activeSpace).map(f=>({value:f.id,label:f.name}))]}]);if(r){doc.folder=r.folder||null;doc.parent=null;changed(doc);dispose();render();}break;}
  case'star-menu':doc.starred=!doc.starred;changed(doc);closeModal();dispose();render();break;
  case'delete':flushEditor();doc.deleted=Date.now();changed(doc);closeModal();navigate('all');toast('Moved to Trash. You can restore it anytime.');break;
  case'restore':doc.deleted=null;changed(doc);closeModal();navigate('doc',doc.id);break;
  case'subpage':flushEditor();newDoc(null,{parent:doc.id,folder:doc.folder});break;
  case'outline':{const headings=[];const walk=n=>{if(n.type==='heading')headings.push({level:n.attrs.level,text:contentText(n)});n.content?.forEach(walk);};walk(doc.content);modal(`<div class="modal-heading"><h2>On this page</h2>${ib('close-modal','Close','x')}</div><div class="choice-list">${headings.map((h,i)=>btn('jump-heading',h.text,'',`data-index="${i}" style="padding-left:${h.level*14}px"`)).join('')||'<p>No headings yet. Add one with /.</p>'}</div>`);break;}
  case'jump-heading':{const n=$$('.writing-area h1,.writing-area h2,.writing-area h3')[+el.dataset.index];closeModal();n?.scrollIntoView({behavior:'smooth',block:'center'});break;}
  case'task-filter':taskFilter=el.dataset.filter;renderMain();break;case'prev-month':month=new Date(month.getFullYear(),month.getMonth()-1,1);renderMain();break;case'next-month':month=new Date(month.getFullYear(),month.getMonth()+1,1);renderMain();break;case'this-month':month=new Date();renderMain();break;
  case'use-template':closeModal();newDoc(templates[+el.dataset.index]);break;case'use-custom-template':closeModal();newDoc({name:doc.title.replace(/ — template$/,''),emoji:doc.emoji,content:doc.content.content});break;
  case'collection-view':doc.collectionView=el.dataset.view;changed(doc);renderCollection(doc);refreshIcons();break;
  case'collection-row':doc.rows.push({id:id(),name:'',status:'To do',date:''});changed(doc);renderCollection(doc);refreshIcons();$$('[data-cell="name"]').at(-1)?.focus();break;
  case'collection-delete':doc.rows=doc.rows.filter(r=>r.id!==el.dataset.id);changed(doc);renderCollection(doc);refreshIcons();break;
  case'collection-open':openCollectionItem(doc,el.dataset.id);break;
  case'collection-column':{const r=await ask('A new collection field',[{name:'name',label:'Field name'},{name:'type',label:'Field type',value:'text',options:['text','number','date','select','checkbox']}]);if(r){doc.columns.push({id:id(),name:r.name,type:r.type});changed(doc);renderCollection(doc);refreshIcons();}break;}
  case'column-rename':{const c=doc.columns.find(c=>c.id===el.dataset.id),r=await ask('Rename field',[{name:'name',label:'Field name',value:c.name}]);if(r){c.name=r.name;changed(doc);renderCollection(doc);refreshIcons();}break;}
  case'board-note':{const r=await ask('A thought to keep',[{name:'text',label:'Your thought'}]);if(r){doc.board.notes.push({id:id(),x:100+doc.board.notes.length*35%700,y:100+doc.board.notes.length*40%400,text:r.text,color:['#fff0b9','#dcebdc','#e7def5'][doc.board.notes.length%3]});changed(doc);window.boardNotes?.();}break;}
  case'board-delete-note':doc.board.notes=doc.board.notes.filter(n=>n.id!==el.dataset.id);changed(doc);window.boardNotes?.();break;
  case'board-undo':doc.board.strokes.pop();changed(doc);window.boardRepaint?.();break;case'board-clear':{const r=await ask('Clear all drawing strokes?',[{name:'confirm',label:'Type CLEAR to confirm'}],'Clear drawing');if(r?.confirm==='CLEAR'){doc.board.strokes=[];changed(doc);window.boardRepaint?.();}break;}
  case'settings':settings();break;case'theme':db.settings.theme=el.dataset.theme;changed();document.documentElement.dataset.theme=db.settings.theme;settings();break;
  case'backup':flushEditor();await persist();if(await window.folio.exportFile({name:'Folio-backup-'+today()+'.json',extension:'json',content:JSON.stringify(db,null,2)}))toast('Workspace backup saved');break;
  case'import':await importFile();break;case'export-menu':menu('Take your words with you',[['export-md','Markdown','file-text'],['export-html','HTML document','globe'],['export-json','Document JSON','braces']]);break;case'export-md':closeModal();exportDoc('md');break;case'export-html':closeModal();exportDoc('html');break;case'export-json':closeModal();exportDoc('json');break;
  case'spaces':menu('Your spaces',[...db.spaces.map(s=>['switch-space',s.name,'circle',`data-id="${s.id}"`]),['add-space','Create a space','plus']]);break;
  case'switch-space':activeSpace=el.dataset.id;db.activeSpace=activeSpace;changed();closeModal();navigate('all');break;
  case'add-space':{const r=await ask('A new space',[{name:'name',label:'Space name'}]);if(r){const s={id:id(),name:r.name,emoji:'◒'};db.spaces.push(s);activeSpace=s.id;db.activeSpace=s.id;changed();navigate('all');}break;}
 }
 }catch(error){console.error(error);toast(error.message,true);}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='n'){e.preventDefault();closeModal();newDoc();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();flushEditor();persist();}});
document.addEventListener('keydown',e=>{if(e.key==='Tab'&&$('#overlay .modal')){const focusable=$$('button:not([hidden]),input,select,a[href],textarea',$('#overlay .modal')).filter(el=>!el.disabled&&el.offsetParent!==null);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
async function boot(){try{db=await window.folio.load();if(!db){db=seed();await window.folio.save(db);}if(db.version!==1||!db.spaces?.length||!Array.isArray(db.docs)||!Array.isArray(db.folders))throw new Error('The workspace format is not supported.');db.settings||={theme:'light',font:'sans'};activeSpace=db.activeSpace||db.spaces[0].id;render();window.folio.onFlush(()=>{flushEditor();persist();});}catch(e){loadFailed=true;$('#app').innerHTML=`<div class="fatal-error"><h1>Your workspace is safe.</h1><p>Folio couldn’t open it, so no changes have been written.</p><pre>${esc(e.message)}</pre><p>Check workspace.json and workspace.json.bak in your Folio app data folder.</p></div>`;}}
boot();


